<?php
require dirname(__DIR__).'/includes/bootstrap.php';
if(!str_starts_with(cfg('DB_NAME'),'seo_autopilot_test'))throw new RuntimeException('This suite requires the isolated test database.');
$credentials=json_decode(file_get_contents(getenv('SEO_TEST_CREDENTIALS') ?: ROOT.'/storage/test-credentials.json'),true);$jar=ROOT.'/storage/test-workflow-cookie.txt';$count=0;
function request(string $path,?array $post=null):array{global $jar;$c=curl_init(cfg('APP_URL').$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>$jar,CURLOPT_COOKIEJAR=>$jar,CURLOPT_PROXY=>'',CURLOPT_TIMEOUT=>30]);if($post!==null)curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$post]);$body=curl_exec($c);$status=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return ['status'=>$status,'body'=>$body];}
function assert_work(bool $ok,string $label):void{global $count;if(!$ok)throw new RuntimeException('FAIL '.$label);$count++;echo "PASS $label\n";}
function form_token(string $path='/dashboard'):string{$r=request($path);preg_match('/name="csrf-token" content="([a-f0-9]+)"/',$r['body'],$m);return $m[1]??'';}
function post_action(string $action,array $data,int $status=200):array{global $csrf;$r=request('/api/v1/'.$action,['csrf'=>$csrf]+$data);assert_work($r['status']===$status,$action.' '.$status.($r['status']!==$status?' got '.$r['status'].' '.$r['body']:''));return json_decode($r['body'],true)??[];}
$csrf=form_token('/login');$r=request('/login',['csrf'=>$csrf,'email'=>$credentials['email'],'password'=>$credentials['password'],'remember'=>'1']);assert_work($r['status']===303,'Login with remember me');$csrf=form_token();$uid=(int)value('SELECT id FROM users WHERE email=?',[$credentials['email']]);$wid=(int)value('SELECT id FROM websites WHERE user_id=? LIMIT 1',[$uid]);
$cookieLines=file($jar);$cookieLines=array_filter($cookieLines,fn($line)=>!str_contains($line,"\tseo_session\t"));file_put_contents($jar,implode('',$cookieLines));assert_work(request('/dashboard')['status']===200,'Remember token restores session');$csrf=form_token();
post_action('website',['domain'=>'https://example.org','name'=>'Quota check','timezone'=>'UTC'],422);
post_action('keyword-bulk',['website_id'=>$wid,'keywords'=>implode("\n",array_map(fn($i)=>'quota '.$i,range(1,60)))],422);
